/**
 * i18n dictionary: English is the guaranteed-complete fallback (translate()
 * falls back to it for any missing key in another language). All 10
 * languages now have full site-wide coverage — translations were produced
 * with AI assistance and should get a native-speaker review pass before
 * being relied on for a production launch, same as any MT-assisted content.
 */
export const SUPPORTED_LANGUAGES = [
  { code: "en", label: "English", translated: true },
  { code: "hi", label: "हिन्दी (Hindi)", translated: true },
  { code: "ta", label: "தமிழ் (Tamil)", translated: true },
  { code: "te", label: "తెలుగు (Telugu)", translated: true },
  { code: "kn", label: "ಕನ್ನಡ (Kannada)", translated: true },
  { code: "ml", label: "മലയാളം (Malayalam)", translated: true },
  { code: "mr", label: "मराठी (Marathi)", translated: true },
  { code: "bn", label: "বাংলা (Bengali)", translated: true },
  { code: "gu", label: "ગુજરાતી (Gujarati)", translated: true },
  { code: "pa", label: "ਪੰਜਾਬੀ (Punjabi)", translated: true },
] as const;

export type LanguageCode = (typeof SUPPORTED_LANGUAGES)[number]["code"];

