  "about.heading": "About ResQ Bharath",
  "about.intro": "ResQ Bharath exists because the minutes right after someone goes missing, an emergency starts, or a disaster hits are the ones that matter most — and they're usually spent making phone calls, not coordinating help.",
  "about.problemHeading": "The problem we're building for",
  "about.problem1": "When a family member goes missing, a stranger collapses in public, or a flood cuts off a neighborhood, the people best positioned to help are often nearby — a volunteer with search-and-rescue training, a hospital with a free bed, a neighbor with a car. What's usually missing isn't willingness, it's a fast, trustworthy way to connect the person who needs help with the people who can give it.",
  "about.problem2": "ResQ Bharath is a single platform for that coordination: missing persons, one-tap SOS, blood donation, and disaster response today, with hospital directories, ambulance requests, volunteer networks, NGO case management, and shelter finding built around the same foundation.",
  "about.believeHeading": "What we believe",
  "about.principle1Title": "Trust is the product",
  "about.principle1Desc": "An emergency platform is only as useful as it is trustworthy. Verification, audit logging, and role-based access aren't afterthoughts here — they're load-bearing.",
  "about.principle2Title": "Privacy protects people",
  "about.principle2Desc": "Public share pages show only what helps find someone — never a reporter's contact details, a patient's medical history, or anything not needed for the case at hand.",
  "about.principle3Title": "Community does the work",
