  "nicci.q.helpline": "आपातकालीन हेल्पलाइन",
  "nicci.q.about": "रेसक्यू भारत के बारे में",
  "nicci.a.greeting": "नमस्कार! मैं आपका रेसक्यू भारत सहायक हूँ। किसी भी सेवा के बारे में पूछें — लापता व्यक्ति, एसओएस, रक्तदान, आपदा राहत और बहुत कुछ।",
  "nicci.a.greetingNamed": "नमस्कार {name}! मैं आपका रेसक्यू भारत सहायक हूँ। किसी भी सेवा के बारे में पूछें — लापता व्यक्ति, एसओएस, रक्तदान, आपदा राहत और बहुत कुछ।",
  "nicci.a.about": "रेसक्यू भारत एक सामुदायिक आपातकालीन मंच है। यह लापता व्यक्ति रिपोर्ट, एसओएस अलर्ट, रक्तदान, आपदा राहत, अभियान और सामुदायिक मदद को एक साथ लाता है — 10 भारतीय भाषाओं में।",
  "nicci.a.helpline": "आपातकालीन हेल्पलाइन — सभी आपात स्थितियाँ 112, पुलिस 100, एम्बुलेंस 108, अग्निशमन 101, महिला 1091, बाल 1098, आपदा 1077।",
  "nicci.a.languages": "रेसक्यू भारत 10 भारतीय भाषाओं में काम करता है। पृष्ठ के शीर्ष पर भाषा मेनू से कभी भी बदलें।",
  "nicci.a.account": "मामले दर्ज करने, कार्यक्रमों में शामिल होने और अलर्ट पाने के लिए ऊपर-दाईं ओर मेनू से साइन अप या लॉग इन करें।",
  "nicci.a.thanks": "मदद करके खुशी हुई! सुरक्षित रहें। 🙏",
  "nicci.a.fallback": "मैं लापता व्यक्ति, एसओएस, रक्तदान, आपदा राहत, अभियान, समुदाय, कैलेंडर और आपातकालीन हेल्पलाइन में मदद कर सकता हूँ। आपको क्या चाहिए?",
