  "about.heading": "रेसक्यू भारत के बारे में",
  "about.intro": "रेसक्यू भारत इसलिए मौजूद है क्योंकि किसी के लापता होने, आपातस्थिति शुरू होने, या आपदा आने के तुरंत बाद के मिनट सबसे महत्वपूर्ण होते हैं — और आमतौर पर वे मिनट मदद के समन्वय के बजाय फ़ोन कॉल करने में बीत जाते हैं।",
  "about.problemHeading": "हम जिस समस्या के लिए निर्माण कर रहे हैं",
  "about.problem1": "जब कोई परिवार का सदस्य लापता हो जाता है, कोई अजनबी सार्वजनिक रूप से गिर जाता है, या कोई बाढ़ किसी मोहल्ले को काट देती है, तो मदद करने के लिए सबसे उपयुक्त लोग अक्सर आस-पास ही होते हैं — खोज एवं बचाव प्रशिक्षण वाला एक स्वयंसेवक, खाली बिस्तर वाला अस्पताल, गाड़ी वाला पड़ोसी। आमतौर पर जो कमी होती है वह इच्छा नहीं, बल्कि मदद चाहने वाले व्यक्ति को मदद देने वालों से जोड़ने का एक तेज़, विश्वसनीय तरीका है।",
  "about.problem2": "रेसक्यू भारत उस समन्वय के लिए एक ही मंच है: आज लापता व्यक्ति, एक-टैप एसओएस, रक्तदान, और आपदा प्रतिक्रिया, साथ ही उसी नींव पर बने अस्पताल निर्देशिका, एम्बुलेंस अनुरोध, स्वयंसेवक नेटवर्क, एनजीओ केस प्रबंधन, और आश्रय खोज।",
  "about.believeHeading": "हम क्या मानते हैं",
  "about.principle1Title": "विश्वास ही उत्पाद है",
  "about.principle1Desc": "एक आपातकालीन मंच उतना ही उपयोगी है जितना वह विश्वसनीय है। सत्यापन, ऑडिट लॉगिंग, और भूमिका-आधारित पहुंच यहां बाद के विचार नहीं हैं — वे नींव हैं।",
  "about.principle2Title": "गोपनीयता लोगों की रक्षा करती है",
  "about.principle2Desc": "सार्वजनिक साझा पेज केवल वही दिखाते हैं जो किसी को खोजने में मदद करता है — कभी भी रिपोर्टर का संपर्क विवरण, मरीज़ का चिकित्सा इतिहास, या मामले के लिए ज़रूरी न हो ऐसा कुछ नहीं।",
  "about.principle3Title": "समुदाय ही काम करता है",
  "about.principle3Desc": "स्वयंसेवक, एनजीओ, अस्पताल, और दाता ही वास्तव में मदद करते हैं — मंच का काम सही अलर्ट सही व्यक्ति तक तेज़ी से पहुंचाना है।",
  "about.principle4Title": "खुले तौर पर, ईमानदारी से निर्मित",
  "about.principle4Desc": "आज चार मॉड्यूल लाइव हैं। बाकी को मॉड्यूल दर मॉड्यूल बनाया जा रहा है, और किसी भी सुविधा को \"पूर्ण\" तब तक नहीं कहा जाता जब तक उसका एंड-टू-एंड परीक्षण न हो जाए।",
  "about.liveHeading": "आज क्या लाइव है",
  "about.live1": "क्यूआर-कोड सार्वजनिक साझा पेज और नज़र आने की समयरेखा के साथ लापता व्यक्ति की रिपोर्टिंग",
  "about.live2": "लाइव लोकेशन और विश्वसनीय-संपर्क सूचना के साथ एक-टैप एसओएस",
  "about.live3": "दाता प्रतिक्रिया ट्रैकिंग के साथ आपातकालीन रक्तदान अनुरोध",
  "about.live4": "आपदा मोड स्थिति रिपोर्टिंग — सुरक्षित चिह्नित करें, या बचाव, भोजन, पानी, या दवा का अनुरोध करें",
  "about.nextHeading": "आगे क्या आ रहा है",
  "about.nextText": "अतिरिक्त सत्यापन के साथ लापता बच्चे और बुज़ुर्ग वर्कफ़्लो, खोए पालतू जानवर की रिपोर्टिंग, अस्पताल और एम्बुलेंस समन्वय, कौशल और प्रतिष्ठा के साथ एक सत्यापित स्वयंसेवक नेटवर्क, एनजीओ केस डैशबोर्ड, आश्रय खोज, एक नेटिव मोबाइल ऐप, और मॉडरेशन एवं विश्लेषण के लिए एडमिन टूलिंग — लगभग इसी क्रम में।",
  "about.createAccount": "खाता बनाएं",
  "about.backHome": "होम पर वापस जाएं",

  "auth.welcomeHeading": "वापसी पर स्वागत है",
