  "nicci.tagline": "உங்கள் டிஜிட்டல் உதவியாளர்",
  "nicci.placeholder": "உங்கள் செய்தியை உள்ளிடவும்…",
  "nicci.send": "அனுப்பு",
  "nicci.mute": "குரலை நிறுத்து",
  "nicci.unmute": "குரல் இயக்கு",
  "nicci.listening": "கேட்கிறேன்…",
  "nicci.micStart": "பேசு",
  "nicci.q.helpline": "அவசர உதவி எண்கள்",
  "nicci.q.about": "ரெஸ்க்யூ பாரத் பற்றி",
  "nicci.a.greeting": "நமஸ்காரம்! நான் உங்கள் ரெஸ்க்யூ பாரத் உதவியாளர். எந்த சேவை பற்றியும் கேளுங்கள் — காணாமல் போனவர்கள், SOS, இரத்த தானம், பேரிடர் நிவாரணம் மற்றும் பல.",
  "nicci.a.greetingNamed": "நமஸ்காரம் {name}! நான் உங்கள் ரெஸ்க்யூ பாரத் உதவியாளர். எந்த சேவை பற்றியும் கேளுங்கள் — காணாமல் போனவர்கள், SOS, இரத்த தானம், பேரிடர் நிவாரணம் மற்றும் பல.",
  "nicci.a.about": "ரெஸ்க்யூ பாரத் ஒரு சமூக அவசர தளம். இது காணாமல் போனவர் அறிக்கைகள், SOS எச்சரிக்கைகள், இரத்த தானம், பேரிடர் நிவாரணம், பிரச்சாரங்கள் மற்றும் சமூக உதவியை ஒன்றிணைக்கிறது — 10 இந்திய மொழிகளில்.",
  "nicci.a.helpline": "அவசர உதவி எண்கள் — அனைத்து அவசரநிலைகள் 112, காவல்துறை 100, ஆம்புலன்ஸ் 108, தீயணைப்பு 101, பெண்கள் 1091, குழந்தை 1098, பேரிடர் 1077.",
  "nicci.a.languages": "ரெஸ்க்யூ பாரத் 10 இந்திய மொழிகளில் இயங்குகிறது. பக்கத்தின் மேலே உள்ள மொழி மெனுவிலிருந்து எப்போது வேண்டுமானாலும் மாற்றலாம்.",
  "nicci.a.account": "வழக்குகளைப் புகாரளிக்க, நிகழ்வுகளுக்கு பதிலளிக்க மற்றும் எச்சரிக்கைகளைப் பெற மேல்-வலது மெனுவிலிருந்து பதிவு செய்யுங்கள் அல்லது உள்நுழையுங்கள்.",
  "nicci.a.thanks": "உதவ மகிழ்ச்சி! பாதுகாப்பாக இருங்கள். 🙏",
  "nicci.a.fallback": "காணாமல் போனவர்கள், SOS, இரத்த தானம், பேரிடர் நிவாரணம், பிரச்சாரங்கள், சமூகம், நாட்காட்டி மற்றும் அவசர உதவி எண்களில் நான் உதவ முடியும். உங்களுக்கு என்ன வேண்டும்?",
