  "infoCategories.heading": "தகவல் வகைகள்",
  "infoCategories.subheading": "சரியான உதவியை விரைவாக கண்டறியவும்",
  "infoCat.community.desc": "உள்ளூர் குழுக்களில் இணையுங்கள், தன்னார்வத் தொண்டு செய்யுங்கள், உங்கள் பகுதியில் நிவாரணத்தை ஒருங்கிணையுங்கள்.",
  "infoCat.helplines.title": "உதவி எண்கள்",
  "infoCat.helplines.desc": "காவல்துறை, ஆம்புலன்ஸ், தீயணைப்பு மற்றும் பேரிடர் நிவாரணத்திற்கான அவசர எண்கள்.",
  "infoCat.calendar.desc": "ஆண்டு முழுவதும் தேசிய விடுமுறைகள், சுகாதார நாட்கள் மற்றும் சமூக நிகழ்வுகள்.",
  "infoCat.awareness.title": "பாதுகாப்பு & விழிப்புணர்வு",
  "infoCat.awareness.desc": "முதலுதவி வழிகாட்டிகள், பாதுகாப்பு குறிப்புகள் மற்றும் சமூக விழிப்புணர்வு கதைகள்.",
  "news.heading": "செய்தி / பத்திரிகை வெளியீடு",
  "news.subheading": "சரிபார்க்கப்பட்ட புதுப்பிப்புகளுக்கான வாயில்",
  "news.empty": "இதுவரை சமீபத்திய புதுப்பிப்புகள் இல்லை",
  "news.viewAll": "அனைத்து செய்திகளையும் காண்க",
