  "about.heading": "ரெஸ்க்யூ பாரத் பற்றி",
  "about.intro": "யாராவது காணாமல் போன, ஒரு அவசரநிலை தொடங்கிய, அல்லது பேரிடர் ஏற்பட்ட உடனடி நிமிடங்கள் மிக முக்கியமானவை — அவை பொதுவாக உதவியை ஒருங்கிணைப்பதற்குப் பதிலாக தொலைபேசி அழைப்புகளில் செலவிடப்படுகின்றன, என்பதால் ரெஸ்க்யூ பாரத் உள்ளது.",
  "about.problemHeading": "நாங்கள் தீர்க்க முயலும் பிரச்சனை",
  "about.problem1": "ஒரு குடும்ப உறுப்பினர் காணாமல் போகும்போது, ஒரு அந்நியர் பொதுவில் விழும்போது, அல்லது ஒரு வெள்ளம் ஒரு பகுதியை துண்டித்துவிடும்போது, உதவ சிறந்த நிலையில் உள்ளவர்கள் பெரும்பாலும் அருகிலேயே இருக்கிறார்கள் — தேடல் மற்றும் மீட்பு பயிற்சி பெற்ற ஒரு தன்னார்வலர், காலி படுக்கை உள்ள ஒரு மருத்துவமனை, காரு உள்ள ஒரு அண்டை வீட்டார். பொதுவாக விடுபடுவது விருப்பம் அல்ல, மாறாக உதவி தேவைப்படுபவரை உதவ முடிந்தவர்களுடன் இணைக்கும் ஒரு வேகமான, நம்பகமான வழிதான்.",
  "about.problem2": "ரெஸ்க்யூ பாரத் அந்த ஒருங்கிணைப்புக்கான ஒரே தளம்: இன்று காணாமல் போனவர்கள், ஒரு-தட்டு எஸ்ஓஎஸ், இரத்த தானம், மற்றும் பேரிடர் மறுமொழி, அதே அடித்தளத்தில் கட்டமைக்கப்பட்ட மருத்துவமனை அடைவு, ஆம்புலன்ஸ் கோரிக்கைகள், தன்னார்வலர் நெட்வொர்க்குகள், என்.ஜி.ஓ. வழக்கு மேலாண்மை, மற்றும் தங்குமிட கண்டுபிடிப்புடன்.",
  "about.believeHeading": "நாங்கள் நம்புவது",
  "about.principle1Title": "நம்பிக்கையே தயாரிப்பு",
  "about.principle1Desc": "ஒரு அவசர தளம் அது எவ்வளவு நம்பகமானதோ அவ்வளவு பயனுள்ளதாக இருக்கும். சரிபார்ப்பு, தணிக்கை பதிவு, மற்றும் பாத்திர-அடிப்படையிலான அணுகல் இங்கு பிந்தைய எண்ணங்கள் அல்ல — அவை அடிப்படை.",
  "about.principle2Title": "தனியுரிமை மக்களைப் பாதுகாக்கிறது",
  "about.principle2Desc": "பொது பகிர்வு பக்கங்கள் ஒருவரைக் கண்டறிய உதவும் தகவலை மட்டுமே காட்டுகின்றன — புகாரளித்தவரின் தொடர்பு விவரங்கள், நோயாளியின் மருத்துவ வரலாறு, அல்லது வழக்குக்குத் தேவையில்லாத எதையும் ஒருபோதும் காட்டாது.",
  "about.principle3Title": "சமூகமே வேலை செய்கிறது",
  "about.principle3Desc": "தன்னார்வலர்கள், என்.ஜி.ஓ.க்கள், மருத்துவமனைகள், மற்றும் தானதாரர்களே உண்மையில் உதவுகிறார்கள் — சரியான எச்சரிக்கையை சரியான நபருக்கு வேகமாக கொண்டு செல்வதே தளத்தின் வேலை.",
  "about.principle4Title": "வெளிப்படையாக, நேர்மையாக கட்டமைக்கப்பட்டது",
  "about.principle4Desc": "இன்று நான்கு தொகுதிகள் செயலில் உள்ளன. மற்றவை தொகுதி தொகுதியாக கட்டமைக்கப்பட்டு வருகின்றன, ஒரு அம்சமும் அது முழுமையாக சோதிக்கப்படும் வரை \"முடிந்தது\" என குறிக்கப்படாது.",
  "about.liveHeading": "இன்று செயலில் உள்ளவை",
  "about.live1": "QR-குறியீடு பொது பகிர்வு பக்கங்கள் மற்றும் பார்வை காலவரிசைகளுடன் காணாமல் போனவர் புகாரளிப்பு",
  "about.live2": "நேரடி இருப்பிடம் மற்றும் நம்பகமான-தொடர்பு அறிவிப்புடன் ஒரு-தட்டு எஸ்ஓஎஸ்",
  "about.live3": "தானதாரர் மறுமொழி கண்காணிப்புடன் அவசர இரத்த தான கோரிக்கைகள்",
  "about.live4": "பேரிடர் பயன்முறை நிலை அறிக்கையிடல் — பாதுகாப்பாக குறிக்கவும், அல்லது மீட்பு, உணவு, தண்ணீர், அல்லது மருந்து கோரவும்",
  "about.nextHeading": "அடுத்து வருவது",
  "about.nextText": "கூடுதல் சரிபார்ப்புடன் காணாமல் போன குழந்தைகள் மற்றும் முதியோர் பணிப்பாய்வுகள், தொலைந்த செல்லப்பிராணி புகாரளிப்பு, மருத்துவமனை மற்றும் ஆம்புலன்ஸ் ஒருங்கிணைப்பு, திறமை மற்றும் நற்பெயருடன் ஒரு சரிபார்க்கப்பட்ட தன்னார்வலர் நெட்வொர்க், என்.ஜி.ஓ. வழக்கு டாஷ்போர்டுகள், தங்குமிட கண்டுபிடிப்பு, ஒரு நேட்டிவ் மொபைல் ஆப், மற்றும் மிதமிஞ்சல் மற்றும் பகுப்பாய்வுக்கான நிர்வாக கருவிகள் — கிட்டத்தட்ட அந்த வரிசையில்.",
