  "authShell.welcomeHeading": "சமூகத்திற்கு வரவேற்கிறோம்",
  "authShell.welcomeSubheading": "ஒரு உயிரைக் காப்பாற்ற உதவத் தயாராக இருக்க நீங்கள் சில படிகள் தொலைவில் இருக்கிறீர்கள்.",
  "authShell.step1Title": "உங்கள் கணக்கை உருவாக்கவும்",
