  "community.form.onlyVerified": "சரிபார்க்கப்பட்ட என்.ஜி.ஓ. அல்லது நிர்வாக கணக்குகள் மட்டுமே சமூகத்தைத் தொடங்க முடியும்.",
  "community.form.heading": "சமூகத்தைத் தொடங்கு",
  "community.form.subheading": "ஒரு-வழி ஒளிபரப்பு சேனல் — நீங்கள் புதுப்பிப்புகளை பதிவிடுவீர்கள், உறுப்பினர்களுக்கு அறிவிக்கப்படும். தொடர்ச்சியான நிவாரண பணிகள், விழிப்புணர்வு பிரச்சாரங்கள், அல்லது திட்ட புதுப்பிப்புகளுக்கு சிறந்தது.",
