  "carousel.slide3Desc": "అత్యవసర రక్త అభ్యర్థనను పోస్ట్ చేయండి లేదా దాతగా నమోదు చేయండి — రక్త వర్గం మరియు నగరం ఆధారంగా సరిపోల్చబడుతుంది.",
