  "carousel.slide4Desc": "క్రియాశీల విపత్తుల సమయంలో మిమ్మల్ని సురక్షితంగా గుర్తించండి, లేదా రెస్క్యూ, ఆహారం, నీరు లేదా మందులు అభ్యర్థించండి.",
