  "about.heading": "రెస్క్యూ భారత్ గురించి",
  "about.intro": "ఎవరైనా తప్పిపోయిన, అత్యవసర పరిస్థితి ప్రారంభమైన, లేదా విపత్తు సంభవించిన వెంటనే వచ్చే నిమిషాలు అత్యంత ముఖ్యమైనవి — మరియు అవి సాధారణంగా సహాయాన్ని సమన్వయం చేయడానికి బదులుగా ఫోన్ కాల్స్ చేయడంలో గడుపుతారు కాబట్టి రెస్క్యూ భారత్ ఉంది.",
  "about.problemHeading": "మేము నిర్మిస్తున్న సమస్య",
  "about.problem1": "కుటుంబ సభ్యుడు తప్పిపోయినప్పుడు, అపరిచితుడు బహిరంగంగా కూలిపోయినప్పుడు, లేదా వరద ఒక ప్రాంతాన్ని కత్తిరించినప్పుడు, సహాయం చేయడానికి ఉత్తమ స్థానంలో ఉన్నవారు తరచుగా సమీపంలోనే ఉంటారు — శోధన మరియు రెస్క్యూ శిక్షణ పొందిన వాలంటీర్, ఖాళీ మంచం ఉన్న ఆసుపత్రి, కారు ఉన్న పొరుగువాడు. సాధారణంగా లోపించేది ఇష్టం కాదు, సహాయం అవసరమైన వ్యక్తిని సహాయం చేయగలవారితో అనుసంధానించే వేగవంతమైన, నమ్మదగిన మార్గం.",
  "about.problem2": "రెస్క్యూ భారత్ ఆ సమన్వయం కోసం ఒకే వేదిక: ఈరోజు తప్పిపోయిన వ్యక్తులు, వన్-టాప్ SOS, రక్తదానం, మరియు విపత్తు ప్రతిస్పందన, అదే పునాదిపై నిర్మించిన ఆసుపత్రి డైరెక్టరీ, అంబులెన్స్ అభ్యర్థనలు, వాలంటీర్ నెట్‌వర్క్‌లు, ఎన్జీఓ కేసు నిర్వహణ, మరియు ఆశ్రయ శోధనతో.",
  "about.believeHeading": "మేము నమ్మేది",
  "about.principle1Title": "నమ్మకమే ఉత్పత్తి",
  "about.principle1Desc": "అత్యవసర వేదిక అది ఎంత నమ్మదగినదో అంత ఉపయోగకరంగా ఉంటుంది. ధృవీకరణ, ఆడిట్ లాగింగ్, మరియు పాత్ర-ఆధారిత యాక్సెస్ ఇక్కడ తర్వాత ఆలోచనలు కావు — అవి పునాది.",
  "about.principle2Title": "గోప్యత ప్రజలను రక్షిస్తుంది",
  "about.principle2Desc": "పబ్లిక్ షేర్ పేజీలు ఎవరినైనా కనుగొనడంలో సహాయపడే వాటిని మాత్రమే చూపిస్తాయి — నివేదికదారు సంప్రదింపు వివరాలు, రోగి వైద్య చరిత్ర, లేదా కేసుకు అవసరం లేని దేనినీ కాదు.",
  "about.principle3Title": "సమాజమే పని చేస్తుంది",
  "about.principle3Desc": "వాలంటీర్లు, ఎన్జీఓలు, ఆసుపత్రులు, మరియు దాతలు నిజంగా సహాయం చేసేవారు — సరైన హెచ్చరికను సరైన వ్యక్తికి వేగంగా చేర్చడమే వేదిక పని.",
  "about.principle4Title": "బహిరంగంగా, నిజాయితీగా నిర్మించబడింది",
  "about.principle4Desc": "ఈరోజు నాలుగు మాడ్యూల్స్ లైవ్‌లో ఉన్నాయి. మిగిలినవి మాడ్యూల్ వారీగా నిర్మించబడుతున్నాయి, ఏ ఫీచర్ కూడా అది పూర్తిగా ఎండ్-టు-ఎండ్ పరీక్షించబడే వరకు \"పూర్తయింది\" అని గుర్తించబడదు.",
  "about.liveHeading": "ఈరోజు లైవ్‌లో ఉన్నవి",
  "about.live1": "QR-కోడ్ పబ్లిక్ షేర్ పేజీలు మరియు దర్శన కాలక్రమాలతో తప్పిపోయిన వ్యక్తి నివేదన",
  "about.live2": "లైవ్ లొకేషన్ మరియు నమ్మకమైన-పరిచయ నోటిఫికేషన్‌తో వన్-టాప్ SOS",
  "about.live3": "దాత ప్రతిస్పందన ట్రాకింగ్‌తో అత్యవసర రక్తదాన అభ్యర్థనలు",
  "about.live4": "విపత్తు మోడ్ స్థితి నివేదన — సురక్షితంగా గుర్తించండి, లేదా రెస్క్యూ, ఆహారం, నీరు, లేదా మందులు అభ్యర్థించండి",
  "about.nextHeading": "తర్వాత ఏమి వస్తుంది",
  "about.nextText": "అదనపు ధృవీకరణతో తప్పిపోయిన పిల్లలు మరియు వృద్ధుల వర్క్‌ఫ్లోలు, తప్పిపోయిన పెంపుడు జంతువుల నివేదన, ఆసుపత్రి మరియు అంబులెన్స్ సమన్వయం, నైపుణ్యం మరియు ఖ్యాతితో ధృవీకరించబడిన వాలంటీర్ నెట్‌వర్క్, ఎన్జీఓ కేసు డాష్‌బోర్డులు, ఆశ్రయ శోధన, స్థానిక మొబైల్ యాప్, మరియు మోడరేషన్ మరియు విశ్లేషణ కోసం అడ్మిన్ టూలింగ్ — దాదాపు ఆ క్రమంలో.",
  "about.createAccount": "ఖాతాను సృష్టించండి",
  "about.backHome": "హోమ్‌కు తిరిగి వెళ్లండి",

