  "community.form.subheading": "ఒక-మార్గం ప్రసార ఛానెల్ — మీరు అప్‌డేట్‌లను పోస్ట్ చేస్తారు, సభ్యులకు తెలియజేయబడుతుంది. కొనసాగుతున్న సహాయ కార్యక్రమాలు, అవగాహన ప్రచారాలు, లేదా ప్రోగ్రామ్ అప్‌డేట్‌లకు అనువైనది.",
