  "nicci.mute": "ಧ್ವನಿ ಮ್ಯೂಟ್ ಮಾಡಿ",
  "nicci.unmute": "ಧ್ವನಿ ಆನ್ ಮಾಡಿ",
  "nicci.listening": "ಆಲಿಸುತ್ತಿದೆ…",
  "nicci.micStart": "ಮಾತನಾಡಿ",
  "nicci.q.helpline": "ತುರ್ತು ಸಹಾಯವಾಣಿಗಳು",
  "nicci.q.about": "ರೆಸ್‌ಕ್ಯೂ ಭಾರತ್ ಬಗ್ಗೆ",
  "nicci.a.greeting": "ನಮಸ್ಕಾರ! ನಾನು ನಿಮ್ಮ ರೆಸ್‌ಕ್ಯೂ ಭಾರತ್ ಸಹಾಯಕ. ಯಾವುದೇ ಸೇವೆಯ ಬಗ್ಗೆ ಕೇಳಿ — ಕಾಣೆಯಾದವರು, SOS, ರಕ್ತದಾನ, ವಿಪತ್ತು ಪರಿಹಾರ ಮತ್ತು ಇನ್ನಷ್ಟು.",
  "nicci.a.greetingNamed": "ನಮಸ್ಕಾರ {name}! ನಾನು ನಿಮ್ಮ ರೆಸ್‌ಕ್ಯೂ ಭಾರತ್ ಸಹಾಯಕ. ಯಾವುದೇ ಸೇವೆಯ ಬಗ್ಗೆ ಕೇಳಿ — ಕಾಣೆಯಾದವರು, SOS, ರಕ್ತದಾನ, ವಿಪತ್ತು ಪರಿಹಾರ ಮತ್ತು ಇನ್ನಷ್ಟು.",
  "nicci.a.about": "ರೆಸ್‌ಕ್ಯೂ ಭಾರತ್ ಒಂದು ಸಮುದಾಯ ತುರ್ತು ವೇದಿಕೆ. ಇದು ಕಾಣೆಯಾದವರ ವರದಿಗಳು, SOS ಎಚ್ಚರಿಕೆಗಳು, ರಕ್ತದಾನ, ವಿಪತ್ತು ಪರಿಹಾರ, ಅಭಿಯಾನಗಳು ಮತ್ತು ಸಮುದಾಯ ಸಹಾಯವನ್ನು ಒಟ್ಟುಗೂಡಿಸುತ್ತದೆ — 10 ಭಾರತೀಯ ಭಾಷೆಗಳಲ್ಲಿ.",
  "nicci.a.helpline": "ತುರ್ತು ಸಹಾಯವಾಣಿಗಳು — ಎಲ್ಲಾ ತುರ್ತುಸ್ಥಿತಿ 112, ಪೊಲೀಸ್ 100, ಆಂಬ್ಯುಲೆನ್ಸ್ 108, ಅಗ್ನಿಶಾಮಕ 101, ಮಹಿಳೆಯರು 1091, ಮಕ್ಕಳು 1098, ವಿಪತ್ತು 1077.",
  "nicci.a.languages": "ರೆಸ್‌ಕ್ಯೂ ಭಾರತ್ 10 ಭಾರತೀಯ ಭಾಷೆಗಳಲ್ಲಿ ಕಾರ್ಯನಿರ್ವಹಿಸುತ್ತದೆ. ಪುಟದ ಮೇಲ್ಭಾಗದ ಭಾಷಾ ಮೆನುವಿನಿಂದ ಯಾವಾಗ ಬೇಕಾದರೂ ಬದಲಾಯಿಸಿ.",
  "nicci.a.account": "ಪ್ರಕರಣಗಳನ್ನು ವರದಿ ಮಾಡಲು, ಕಾರ್ಯಕ್ರಮಗಳಿಗೆ RSVP ಮಾಡಲು ಮತ್ತು ಎಚ್ಚರಿಕೆಗಳನ್ನು ಪಡೆಯಲು ಮೇಲಿನ-ಬಲ ಮೆನುವಿನಿಂದ ಸೈನ್ ಅಪ್ ಅಥವಾ ಲಾಗಿನ್ ಮಾಡಿ.",
  "nicci.a.thanks": "ಸಹಾಯ ಮಾಡಲು ಸಂತೋಷ! ಸುರಕ್ಷಿತವಾಗಿರಿ. 🙏",
  "nicci.a.fallback": "ಕಾಣೆಯಾದವರು, SOS, ರಕ್ತದಾನ, ವಿಪತ್ತು ಪರಿಹಾರ, ಅಭಿಯಾನಗಳು, ಸಮುದಾಯ, ಕ್ಯಾಲೆಂಡರ್ ಮತ್ತು ತುರ್ತು ಸಹಾಯವಾಣಿಗಳಲ್ಲಿ ನಾನು ಸಹಾಯ ಮಾಡಬಲ್ಲೆ. ನಿಮಗೆ ಏನು ಬೇಕು?",
