  "about.heading": "ರೆಸ್ಕ್ಯೂ ಭಾರತ್ ಬಗ್ಗೆ",
  "about.intro": "ಯಾರಾದರೂ ಕಾಣೆಯಾದ, ತುರ್ತುಸ್ಥಿತಿ ಪ್ರಾರಂಭವಾದ, ಅಥವಾ ವಿಪತ್ತು ಸಂಭವಿಸಿದ ತಕ್ಷಣದ ನಿಮಿಷಗಳೇ ಅತ್ಯಂತ ಮುಖ್ಯವಾದವು — ಮತ್ತು ಅವು ಸಾಮಾನ್ಯವಾಗಿ ಸಹಾಯವನ್ನು ಸಮನ್ವಯಗೊಳಿಸುವ ಬದಲು ಫೋನ್ ಕರೆಗಳನ್ನು ಮಾಡುವುದರಲ್ಲಿ ಕಳೆಯಲ್ಪಡುತ್ತವೆ ಎಂಬ ಕಾರಣಕ್ಕಾಗಿ ರೆಸ್ಕ್ಯೂ ಭಾರತ್ ಅಸ್ತಿತ್ವದಲ್ಲಿದೆ.",
  "about.problemHeading": "ನಾವು ಪರಿಹರಿಸಲು ನಿರ್ಮಿಸುತ್ತಿರುವ ಸಮಸ್ಯೆ",
  "about.problem1": "ಕುಟುಂಬ ಸದಸ್ಯರೊಬ್ಬರು ಕಾಣೆಯಾದಾಗ, ಅಪರಿಚಿತರೊಬ್ಬರು ಸಾರ್ವಜನಿಕವಾಗಿ ಕುಸಿದುಬಿದ್ದಾಗ, ಅಥವಾ ಪ್ರವಾಹವು ಒಂದು ಪ್ರದೇಶವನ್ನು ಕಡಿತಗೊಳಿಸಿದಾಗ, ಸಹಾಯ ಮಾಡಲು ಉತ್ತಮ ಸ್ಥಾನದಲ್ಲಿರುವ ಜನರು ಸಾಮಾನ್ಯವಾಗಿ ಹತ್ತಿರದಲ್ಲೇ ಇರುತ್ತಾರೆ — ಶೋಧ ಮತ್ತು ರಕ್ಷಣಾ ತರಬೇತಿ ಪಡೆದ ಸ್ವಯಂಸೇವಕ, ಖಾಲಿ ಹಾಸಿಗೆ ಇರುವ ಆಸ್ಪತ್ರೆ, ಕಾರು ಹೊಂದಿರುವ ನೆರೆಹೊರೆಯವರು. ಸಾಮಾನ್ಯವಾಗಿ ಕೊರತೆ ಇರುವುದು ಇಚ್ಛಾಶಕ್ತಿಯಲ್ಲ, ಬದಲಿಗೆ ಸಹಾಯ ಬೇಕಿರುವ ವ್ಯಕ್ತಿಯನ್ನು ಸಹಾಯ ನೀಡಬಲ್ಲವರೊಂದಿಗೆ ಸಂಪರ್ಕಿಸುವ ವೇಗದ, ವಿಶ್ವಾಸಾರ್ಹ ಮಾರ್ಗ.",
  "about.problem2": "ರೆಸ್ಕ್ಯೂ ಭಾರತ್ ಆ ಸಮನ್ವಯಕ್ಕಾಗಿ ಒಂದೇ ವೇದಿಕೆ: ಇಂದು ಕಾಣೆಯಾದ ವ್ಯಕ್ತಿಗಳು, ಒಂದೇ-ಟ್ಯಾಪ್ SOS, ರಕ್ತದಾನ, ಮತ್ತು ವಿಪತ್ತು ಪ್ರತಿಕ್ರಿಯೆ, ಅದೇ ಅಡಿಪಾಯದ ಮೇಲೆ ನಿರ್ಮಿಸಲಾದ ಆಸ್ಪತ್ರೆ ಡೈರೆಕ್ಟರಿಗಳು, ಆಂಬ್ಯುಲೆನ್ಸ್ ವಿನಂತಿಗಳು, ಸ್ವಯಂಸೇವಕ ಜಾಲಗಳು, ಎನ್‌ಜಿಒ ಪ್ರಕರಣ ನಿರ್ವಹಣೆ, ಮತ್ತು ಆಶ್ರಯ ಶೋಧನೆಯೊಂದಿಗೆ.",
  "about.believeHeading": "ನಾವು ನಂಬುವುದು",
  "about.principle1Title": "ನಂಬಿಕೆಯೇ ಉತ್ಪನ್ನ",
  "about.principle1Desc": "ತುರ್ತು ವೇದಿಕೆಯು ಅದು ಎಷ್ಟು ವಿಶ್ವಾಸಾರ್ಹವೋ ಅಷ್ಟೇ ಉಪಯುಕ್ತವಾಗಿರುತ್ತದೆ. ಪರಿಶೀಲನೆ, ಆಡಿಟ್ ಲಾಗಿಂಗ್, ಮತ್ತು ಪಾತ್ರ-ಆಧಾರಿತ ಪ್ರವೇಶ ಇಲ್ಲಿ ನಂತರದ ಆಲೋಚನೆಗಳಲ್ಲ — ಅವು ಅಡಿಪಾಯ.",
  "about.principle2Title": "ಗೌಪ್ಯತೆ ಜನರನ್ನು ರಕ್ಷಿಸುತ್ತದೆ",
  "about.principle2Desc": "ಸಾರ್ವಜನಿಕ ಹಂಚಿಕೆ ಪುಟಗಳು ಯಾರನ್ನಾದರೂ ಹುಡುಕಲು ಸಹಾಯ ಮಾಡುವುದನ್ನು ಮಾತ್ರ ತೋರಿಸುತ್ತವೆ — ವರದಿಗಾರರ ಸಂಪರ್ಕ ವಿವರಗಳು, ರೋಗಿಯ ವೈದ್ಯಕೀಯ ಇತಿಹಾಸ, ಅಥವಾ ಪ್ರಕರಣಕ್ಕೆ ಅಗತ್ಯವಿಲ್ಲದ ಯಾವುದನ್ನೂ ಎಂದಿಗೂ ಅಲ್ಲ.",
  "about.principle3Title": "ಸಮುದಾಯವೇ ಕೆಲಸ ಮಾಡುತ್ತದೆ",
  "about.principle3Desc": "ಸ್ವಯಂಸೇವಕರು, ಎನ್‌ಜಿಒಗಳು, ಆಸ್ಪತ್ರೆಗಳು, ಮತ್ತು ದಾನಿಗಳೇ ನಿಜವಾಗಿ ಸಹಾಯ ಮಾಡುವವರು — ಸರಿಯಾದ ಎಚ್ಚರಿಕೆಯನ್ನು ಸರಿಯಾದ ವ್ಯಕ್ತಿಗೆ ವೇಗವಾಗಿ ತಲುಪಿಸುವುದೇ ವೇದಿಕೆಯ ಕೆಲಸ.",
  "about.principle4Title": "ಬಹಿರಂಗವಾಗಿ, ಪ್ರಾಮಾಣಿಕವಾಗಿ ನಿರ್ಮಿಸಲಾಗಿದೆ",
  "about.principle4Desc": "ಇಂದು ನಾಲ್ಕು ಮಾಡ್ಯೂಲ್‌ಗಳು ಲೈವ್ ಆಗಿವೆ. ಉಳಿದವುಗಳನ್ನು ಮಾಡ್ಯೂಲ್‌ನಿಂದ ಮಾಡ್ಯೂಲ್‌ಗೆ ನಿರ್ಮಿಸಲಾಗುತ್ತಿದೆ, ಯಾವುದೇ ವೈಶಿಷ್ಟ್ಯವನ್ನು ಅದು ನಿಜವಾಗಿ ಎಂಡ್-ಟು-ಎಂಡ್ ಪರೀಕ್ಷಿಸುವವರೆಗೆ \"ಪೂರ್ಣಗೊಂಡಿದೆ\" ಎಂದು ಗುರುತಿಸಲಾಗುವುದಿಲ್ಲ.",
  "about.liveHeading": "ಇಂದು ಲೈವ್ ಆಗಿರುವುದು",
  "about.live1": "QR-ಕೋಡ್ ಸಾರ್ವಜನಿಕ ಹಂಚಿಕೆ ಪುಟಗಳು ಮತ್ತು ಕಾಣಿಸಿಕೊಂಡ ಟೈಮ್‌ಲೈನ್‌ಗಳೊಂದಿಗೆ ಕಾಣೆಯಾದ ವ್ಯಕ್ತಿಯ ವರದಿ",
  "about.live2": "ಲೈವ್ ಸ್ಥಳ ಮತ್ತು ವಿಶ್ವಾಸಾರ್ಹ-ಸಂಪರ್ಕ ಅಧಿಸೂಚನೆಯೊಂದಿಗೆ ಒಂದೇ-ಟ್ಯಾಪ್ SOS",
  "about.live3": "ದಾನಿ ಪ್ರತಿಕ್ರಿಯೆ ಟ್ರ್ಯಾಕಿಂಗ್‌ನೊಂದಿಗೆ ತುರ್ತು ರಕ್ತದಾನ ವಿನಂತಿಗಳು",
  "about.live4": "ವಿಪತ್ತು ಮೋಡ್ ಸ್ಥಿತಿ ವರದಿ — ಸುರಕ್ಷಿತ ಎಂದು ಗುರುತಿಸಿ, ಅಥವಾ ರಕ್ಷಣೆ, ಆಹಾರ, ನೀರು, ಅಥವಾ ಔಷಧಿಯನ್ನು ವಿನಂತಿಸಿ",
  "about.nextHeading": "ಮುಂದೆ ಬರುತ್ತಿರುವುದು",
  "about.nextText": "ಹೆಚ್ಚುವರಿ ಪರಿಶೀಲನೆಯೊಂದಿಗೆ ಕಾಣೆಯಾದ ಮಕ್ಕಳು ಮತ್ತು ಹಿರಿಯರ ಕಾರ್ಯಹರಿವುಗಳು, ಕಳೆದುಹೋದ ಸಾಕುಪ್ರಾಣಿ ವರದಿ, ಆಸ್ಪತ್ರೆ ಮತ್ತು ಆಂಬ್ಯುಲೆನ್ಸ್ ಸಮನ್ವಯ, ಕೌಶಲ ಮತ್ತು ಖ್ಯಾತಿಯೊಂದಿಗೆ ಪರಿಶೀಲಿತ ಸ್ವಯಂಸೇವಕ ಜಾಲ, ಎನ್‌ಜಿಒ ಪ್ರಕರಣ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ಗಳು, ಆಶ್ರಯ ಶೋಧನೆ, ಸ್ಥಳೀಯ ಮೊಬೈಲ್ ಆಪ್, ಮತ್ತು ಮಾಡರೇಶನ್ ಮತ್ತು ವಿಶ್ಲೇಷಣೆಗಾಗಿ ನಿರ್ವಾಹಕ ಪರಿಕರಗಳು — ಬಹುತೇಕ ಆ ಕ್ರಮದಲ್ಲಿ.",
  "about.createAccount": "ಖಾತೆ ರಚಿಸಿ",
  "about.backHome": "ಮುಖಪುಟಕ್ಕೆ ಹಿಂತಿರುಗಿ",

