  "campaigns.list.viewButton": "ವೀಕ್ಷಿಸಿ ಮತ್ತು ನೋಂದಾಯಿಸಿ",

  "campaigns.form.onlyVerified": "ಪರಿಶೀಲಿಸಿದ ಎನ್‌ಜಿಒ ಅಥವಾ ಅಡ್ಮಿನ್ ಖಾತೆಗಳು ಮಾತ್ರ ಅಭಿಯಾನವನ್ನು ಪ್ರಾರಂಭಿಸಬಹುದು.",
  "campaigns.form.heading": "ಅಭಿಯಾನ ಪ್ರಾರಂಭಿಸಿ",
  "campaigns.form.subheading": "ಜಾಗೃತಿ ಅಭಿಯಾನಗಳು, ಹ್ಯಾಕಥಾನ್‌ಗಳು, ಸ್ವಚ್ಛತಾ ಅಭಿಯಾನಗಳು, ಸಸಿ ನೆಡುವಿಕೆ ಮತ್ತು ಪರಿಹಾರ ಶಿಬಿರಗಳು — ಇಲ್ಲಿ ಪ್ರಕಟಿಸಿ ಮತ್ತು ಸಮುದಾಯವನ್ನು ನೋಂದಾಯಿಸಲು ಬಿಡಿ.",
