  "nicci.micStart": "സംസാരിക്കുക",
  "nicci.q.helpline": "അടിയന്തര ഹെൽപ്പ്‌ലൈനുകൾ",
  "nicci.q.about": "റെസ്ക്യൂ ഭാരത് കുറിച്ച്",
  "nicci.a.greeting": "നമസ്കാരം! ഞാൻ നിങ്ങളുടെ റെസ്ക്യൂ ഭാരത് അസിസ്റ്റന്റ്. ഏത് സേവനത്തെക്കുറിച്ചും ചോദിക്കൂ — കാണാതായവർ, SOS, രക്തദാനം, ദുരന്ത നിവാരണം എന്നിവയും അതിലേറെയും.",
  "nicci.a.greetingNamed": "നമസ്കാരം {name}! ഞാൻ നിങ്ങളുടെ റെസ്ക്യൂ ഭാരത് അസിസ്റ്റന്റ്. ഏത് സേവനത്തെക്കുറിച്ചും ചോദിക്കൂ — കാണാതായവർ, SOS, രക്തദാനം, ദുരന്ത നിവാരണം എന്നിവയും അതിലേറെയും.",
  "nicci.a.about": "റെസ്ക്യൂ ഭാരത് ഒരു സമൂഹ അടിയന്തര പ്ലാറ്റ്‌ഫോമാണ്. കാണാതായവരുടെ റിപ്പോർട്ടുകൾ, SOS അലേർട്ടുകൾ, രക്തദാനം, ദുരന്ത നിവാരണം, കാമ്പെയ്‌നുകൾ, സമൂഹ സഹായം എന്നിവ ഇത് ഒരുമിച്ച് കൊണ്ടുവരുന്നു — 10 ഇന്ത്യൻ ഭാഷകളിൽ.",
  "nicci.a.helpline": "അടിയന്തര ഹെൽപ്പ്‌ലൈനുകൾ — എല്ലാ അടിയന്തരാവസ്ഥകൾ 112, പോലീസ് 100, ആംബുലൻസ് 108, ഫയർ 101, സ്ത്രീകൾ 1091, കുട്ടികൾ 1098, ദുരന്തം 1077.",
  "nicci.a.languages": "റെസ്ക്യൂ ഭാരത് 10 ഇന്ത്യൻ ഭാഷകളിൽ പ്രവർത്തിക്കുന്നു. പേജിന്റെ മുകളിലുള്ള ഭാഷാ മെനുവിൽ നിന്ന് എപ്പോൾ വേണമെങ്കിലും മാറ്റാം.",
  "nicci.a.account": "കേസുകൾ റിപ്പോർട്ട് ചെയ്യാനും പരിപാടികളിൽ RSVP ചെയ്യാനും അലേർട്ടുകൾ ലഭിക്കാനും മുകളിൽ-വലത് മെനുവിൽ നിന്ന് സൈൻ അപ്പ് അല്ലെങ്കിൽ ലോഗിൻ ചെയ്യുക.",
  "nicci.a.thanks": "സഹായിക്കാൻ സന്തോഷം! സുരക്ഷിതരായിരിക്കൂ. 🙏",
  "nicci.a.fallback": "കാണാതായവർ, SOS, രക്തദാനം, ദുരന്ത നിവാരണം, കാമ്പെയ്‌നുകൾ, സമൂഹം, കലണ്ടർ, അടിയന്തര ഹെൽപ്പ്‌ലൈനുകൾ എന്നിവയിൽ ഞാൻ സഹായിക്കാം. നിങ്ങൾക്ക് എന്താണ് വേണ്ടത്?",
