  "authShell.welcomeHeading": "സമൂഹത്തിലേക്ക് സ്വാഗതം",
  "authShell.welcomeSubheading": "ഒരു ജീവൻ രക്ഷിക്കാൻ സഹായിക്കാൻ തയ്യാറാകാൻ നിങ്ങൾ ഏതാനും ചുവടുകൾ അകലെയാണ്.",
  "authShell.step1Title": "നിങ്ങളുടെ അക്കൗണ്ട് സൃഷ്ടിക്കുക",
  "authShell.step1Desc": "ഒരു സമയത്ത് ഒരു ചോദ്യം — ഒരു മിനിറ്റിൽ താഴെ സമയമെടുക്കും.",
  "authShell.step2Title": "നിങ്ങളുടെ ഫോൺ പരിശോധിച്ചുറപ്പിക്കുക",
  "authShell.step2Desc": "അലേർട്ടുകളും OTP ലോഗിനുകളും ശരിയായ വ്യക്തിയിലേക്ക് എത്താൻ.",
  "authShell.step3Title": "സമീപത്ത് പൊരുത്തപ്പെടുക",
  "authShell.step3Desc": "നിങ്ങളുടെ നഗരത്തിനടുത്ത് SOS, രക്ത അഭ്യർത്ഥനകൾ, ദുരന്ത മുന്നറിയിപ്പുകൾ.",
