  "community.form.onlyVerified": "പരിശോധിച്ചുറപ്പിച്ച എൻ.ജി.ഒ. അല്ലെങ്കിൽ അഡ്മിൻ അക്കൗണ്ടുകൾക്ക് മാത്രമേ സമൂഹം ആരംഭിക്കാൻ കഴിയൂ.",
  "community.form.heading": "സമൂഹം ആരംഭിക്കുക",
  "community.form.subheading": "ഒരു-വഴി പ്രക്ഷേപണ ചാനൽ — നിങ്ങൾ അപ്‌ഡേറ്റുകൾ പോസ്റ്റ് ചെയ്യുന്നു, അംഗങ്ങളെ അറിയിക്കും. തുടരുന്ന ദുരിതാശ്വാസ പ്രവർത്തനങ്ങൾ, ബോധവൽക്കരണ കാമ്പയിനുകൾ, അല്ലെങ്കിൽ പ്രോഗ്രാം അപ്‌ഡേറ്റുകൾക്ക് മികച്ചത്.",
