  "feed.sidebar.spottedHeading": "ആരെയെങ്കിലും കണ്ടോ?",
  "feed.sidebar.spottedBody": "പോസ്റ്റ് തുറന്ന് “ഞാൻ ഈ വ്യക്തിയെ കണ്ടു” അമർത്തുക — കുടുംബത്തിന് ഉടൻ അറിയിപ്പ് ലഭിക്കും.",
  "feed.sidebar.shareHeading": "പങ്കിടൽ ജീവൻ രക്ഷിക്കുന്നു",
  "feed.sidebar.shareBody": "ഓരോ പങ്കിടലും കാണാതായ വ്യക്തിയിൽ കൂടുതൽ കണ്ണുകൾ എത്തിക്കുന്നു. നിങ്ങളുടെ പ്രാദേശിക ഗ്രൂപ്പുകളിൽ പോസ്റ്റുകൾ പങ്കിടുക.",
  "feed.sidebar.emergencyHeading": "ഉടനടി അപകടത്തിലാണോ?",
  "feed.sidebar.emergencyBody": "ആദ്യം 112ൽ വിളിക്കുക. ഈ പ്ലാറ്റ്ഫോം ഔദ്യോഗിക അടിയന്തര സേവനങ്ങൾക്ക് അനുബന്ധം മാത്രമാണ്.",
  "gallery.heading": "സേവന ഗാലറി",
  "gallery.subheading": "ഇന്ത്യയിലുടനീളമുള്ള പരിശോധിച്ച NGOകളുടെ ദുരിതാശ്വാസ, സേവന പ്രവർത്തനങ്ങൾ — എല്ലാവർക്കും കാണാം.",
  "gallery.empty": "ഇതുവരെ ഫോട്ടോകളില്ല — പരിശോധിച്ച NGOകൾക്ക് അവരുടെ സേവന പ്രവർത്തനങ്ങൾ ഇവിടെ പ്രസിദ്ധീകരിക്കാം.",
