  "gallery.uploading": "പ്രസിദ്ധീകരിക്കുന്നു…",
  "awareness.heading": "പൊതു അവബോധം",
  "awareness.q1": "അടിയന്തരാവസ്ഥയിൽ ഓരോ മിനിറ്റും വിലപ്പെട്ടതാണ് — തയ്യാറായ സമൂഹമാണ് ഏറ്റവും വേഗതയുള്ള ആദ്യ രക്ഷകൻ.",
  "awareness.q2": "ഒരു രക്തദാനം മൂന്ന് ജീവനുകൾ വരെ രക്ഷിക്കും.",
  "awareness.q3": "കാണാതായവരുടെ പോസ്റ്റ് പങ്കിടുക — ഓരോ അധിക കണ്ണും അവരെ വീട്ടിലേക്ക് അടുപ്പിക്കുന്നു.",
  "awareness.q4": "ദുരന്തം വരുംമുമ്പ് നിങ്ങളുടെ അടുത്തുള്ള അഭയകേന്ദ്രം, ആശുപത്രി, ഹെൽപ്പ്‌ലൈൻ എന്നിവ അറിഞ്ഞിരിക്കുക.",
  "awareness.q5": "മറ്റുള്ളവരോടുള്ള സേവനമാണ് ഈ ഭൂമിയിലെ നമ്മുടെ വാസത്തിന്റെ വാടക.",
