  "about.heading": "रेस्क्यू भारतबद्दल",
  "about.intro": "कोणी बेपत्ता होण्याच्या, आणीबाणी सुरू होण्याच्या, किंवा आपत्ती येण्याच्या लगेचच्या मिनिटांना सर्वात जास्त महत्त्व असते — आणि ती सहसा मदतीचे समन्वय साधण्याऐवजी फोन कॉल करण्यात घालवली जातात, यामुळेच रेस्क्यू भारत अस्तित्वात आहे.",
  "about.problemHeading": "आम्ही ज्यासाठी तयार करत आहोत ती समस्या",
  "about.problem1": "जेव्हा एखादा कुटुंब सदस्य बेपत्ता होतो, एखादा अनोळखी व्यक्ती सार्वजनिकरित्या कोसळतो, किंवा पूर एखादा परिसर तोडतो, तेव्हा मदत करण्यास सर्वोत्तम स्थितीत असलेले लोक बहुधा जवळच असतात — शोध आणि बचाव प्रशिक्षण घेतलेला स्वयंसेवक, रिकामा बेड असलेले रुग्णालय, गाडी असलेला शेजारी. सहसा जी गोष्ट कमी असते ती इच्छाशक्ती नसते, तर मदत हवी असलेल्या व्यक्तीला मदत देऊ शकणाऱ्यांशी जोडण्याचा एक जलद, विश्वासार्ह मार्ग असतो.",
  "about.problem2": "रेस्क्यू भारत त्या समन्वयासाठी एकच व्यासपीठ आहे: आज बेपत्ता व्यक्ती, वन-टॅप SOS, रक्तदान, आणि आपत्ती प्रतिसाद, त्याच पायावर बांधलेले रुग्णालय निर्देशिका, रुग्णवाहिका विनंत्या, स्वयंसेवक नेटवर्क, एनजीओ प्रकरण व्यवस्थापन, आणि आश्रयस्थान शोधासह.",
  "about.believeHeading": "आम्ही काय मानतो",
  "about.principle1Title": "विश्वास हेच उत्पादन आहे",
  "about.principle1Desc": "आणीबाणी व्यासपीठ जितके विश्वासार्ह असते तितकेच ते उपयुक्त असते. पडताळणी, ऑडिट लॉगिंग, आणि भूमिका-आधारित प्रवेश इथे नंतरचे विचार नाहीत — ते पायाभूत आहेत.",
  "about.principle2Title": "गोपनीयता लोकांचे संरक्षण करते",
  "about.principle2Desc": "सार्वजनिक शेअर पृष्ठे केवळ एखाद्याला शोधण्यास मदत करणारी माहिती दाखवतात — अहवाल देणाऱ्याचे संपर्क तपशील, रुग्णाचा वैद्यकीय इतिहास, किंवा प्रकरणासाठी आवश्यक नसलेले काहीही कधीही दाखवत नाहीत.",
  "about.principle3Title": "समुदाय काम करतो",
  "about.principle3Desc": "स्वयंसेवक, एनजीओ, रुग्णालये, आणि दाते हेच खरोखर मदत करतात — योग्य अलर्ट योग्य व्यक्तीपर्यंत वेगाने पोहोचवणे हे व्यासपीठाचे काम आहे.",
  "about.principle4Title": "उघडपणे, प्रामाणिकपणे तयार केले",
  "about.principle4Desc": "आज चार मॉड्यूल्स लाइव्ह आहेत. बाकीचे मॉड्यूलनुसार मॉड्यूल तयार केले जात आहेत, कोणतेही वैशिष्ट्य ते खरोखर एंड-टू-एंड चाचणी होईपर्यंत \"पूर्ण\" म्हणून चिन्हांकित केले जात नाही.",
  "about.liveHeading": "आज काय लाइव्ह आहे",
  "about.live1": "QR-कोड सार्वजनिक शेअर पृष्ठे आणि दिसल्याच्या टाइमलाइनसह बेपत्ता व्यक्तीचा अहवाल",
  "about.live2": "लाइव्ह लोकेशन आणि विश्वासू-संपर्क सूचनेसह वन-टॅप SOS",
  "about.live3": "दाता प्रतिसाद ट्रॅकिंगसह आणीबाणी रक्तदान विनंत्या",
  "about.live4": "आपत्ती मोड स्थिती अहवाल — सुरक्षित म्हणून चिन्हांकित करा, किंवा बचाव, अन्न, पाणी, किंवा औषध विनंती करा",
  "about.nextHeading": "पुढे काय येत आहे",
  "about.nextText": "अतिरिक्त पडताळणीसह बेपत्ता मुले आणि वृद्ध कार्यप्रवाह, हरवलेल्या पाळीव प्राण्याचा अहवाल, रुग्णालय आणि रुग्णवाहिका समन्वय, कौशल्य आणि प्रतिष्ठेसह सत्यापित स्वयंसेवक नेटवर्क, एनजीओ प्रकरण डॅशबोर्ड, आश्रयस्थान शोध, एक नेटिव्ह मोबाइल अॅप, आणि मॉडरेशन आणि विश्लेषणासाठी प्रशासक साधने — साधारण त्याच क्रमाने.",
  "about.createAccount": "खाते तयार करा",
  "about.backHome": "मुख्यपृष्ठावर परत जा",

