  "nicci.q.helpline": "জরুরি হেল্পলাইন",
  "nicci.q.about": "রেসকিউ ভারত সম্পর্কে",
  "nicci.a.greeting": "নমস্কার! আমি আপনার রেসকিউ ভারত সহকারী। যেকোনো পরিষেবা সম্পর্কে জিজ্ঞাসা করুন — নিখোঁজ ব্যক্তি, SOS, রক্তদান, দুর্যোগ ত্রাণ এবং আরও অনেক কিছু।",
  "nicci.a.greetingNamed": "নমস্কার {name}! আমি আপনার রেসকিউ ভারত সহকারী। যেকোনো পরিষেবা সম্পর্কে জিজ্ঞাসা করুন — নিখোঁজ ব্যক্তি, SOS, রক্তদান, দুর্যোগ ত্রাণ এবং আরও অনেক কিছু।",
  "nicci.a.about": "রেসকিউ ভারত একটি সম্প্রদায় জরুরি প্ল্যাটফর্ম। এটি নিখোঁজ ব্যক্তির রিপোর্ট, SOS সতর্কতা, রক্তদান, দুর্যোগ ত্রাণ, প্রচারাভিযান এবং সম্প্রদায়ের সাহায্য একত্র করে — 10টি ভারতীয় ভাষায়।",
  "nicci.a.helpline": "জরুরি হেল্পলাইন — সমস্ত জরুরি 112, পুলিশ 100, অ্যাম্বুলেন্স 108, দমকল 101, নারী 1091, শিশু 1098, দুর্যোগ 1077।",
  "nicci.a.languages": "রেসকিউ ভারত 10টি ভারতীয় ভাষায় কাজ করে। পৃষ্ঠার উপরে ভাষা মেনু থেকে যেকোনো সময় পরিবর্তন করুন।",
  "nicci.a.account": "মামলা রিপোর্ট করতে, অনুষ্ঠানে RSVP করতে এবং সতর্কতা পেতে উপরে-ডানদিকের মেনু থেকে সাইন আপ বা লগ ইন করুন।",
  "nicci.a.thanks": "সাহায্য করে খুশি! নিরাপদ থাকুন। 🙏",
  "nicci.a.fallback": "নিখোঁজ ব্যক্তি, SOS, রক্তদান, দুর্যোগ ত্রাণ, প্রচারাভিযান, সম্প্রদায়, ক্যালেন্ডার এবং জরুরি হেল্পলাইনে আমি সাহায্য করতে পারি। আপনার কী প্রয়োজন?",
