  "carousel.slide1Desc": "এক মিনিটেরও কম সময়ে ছবি সহ একটি রিপোর্ট ফাইল করুন, এবং QR কোডের মাধ্যমে তাৎক্ষণিকভাবে শেয়ার করুন।",
  "carousel.slide1Cta": "কেউ নিখোঁজ হয়েছে বলে রিপোর্ট করুন",
  "carousel.slide2Title": "একটি ট্যাপ আপনার দিকে সাহায্য পাঠায়",
  "carousel.slide2Desc": "SOS আপনার লাইভ লোকেশন বিশ্বস্ত পরিচিতি এবং কাছাকাছি যাচাইকৃত স্বেচ্ছাসেবকদের সাথে শেয়ার করে।",
  "carousel.slide2Cta": "SOS কীভাবে কাজ করে তা দেখুন",
