  "carousel.slide3Desc": "জরুরি রক্তের অনুরোধ পোস্ট করুন অথবা দাতা হিসেবে নিবন্ধন করুন — রক্তের গ্রুপ এবং শহর অনুযায়ী মিলিয়ে দেওয়া হয়।",
  "carousel.slide3Cta": "রক্তের অনুরোধ দেখুন",
  "carousel.slide4Title": "দুর্যোগ ঘটলে সমন্বিত প্রতিক্রিয়া",
  "carousel.slide4Desc": "সক্রিয় দুর্যোগের সময় নিজেকে নিরাপদ হিসেবে চিহ্নিত করুন, অথবা উদ্ধার, খাদ্য, পানি বা ওষুধের জন্য অনুরোধ করুন।",
