  "about.heading": "রেসকিউ ভারত সম্পর্কে",
  "about.intro": "কেউ নিখোঁজ হওয়ার, একটি জরুরি অবস্থা শুরু হওয়ার, বা একটি দুর্যোগ আঘাত হানার ঠিক পরের মিনিটগুলোই সবচেয়ে গুরুত্বপূর্ণ — এবং সেগুলো সাধারণত সাহায্য সমন্বয় করার পরিবর্তে ফোন কল করাতে ব্যয় হয়, এই কারণেই রেসকিউ ভারতর অস্তিত্ব।",
  "about.problemHeading": "আমরা যে সমস্যার জন্য তৈরি করছি",
  "about.problem1": "যখন একজন পরিবারের সদস্য নিখোঁজ হন, একজন অপরিচিত ব্যক্তি প্রকাশ্যে ভেঙে পড়েন, বা একটি বন্যা একটি এলাকাকে বিচ্ছিন্ন করে দেয়, তখন সাহায্য করার জন্য সবচেয়ে ভালো অবস্থানে থাকা মানুষগুলো প্রায়শই কাছাকাছিই থাকে — অনুসন্ধান ও উদ্ধার প্রশিক্ষণপ্রাপ্ত একজন স্বেচ্ছাসেবক, খালি বেড থাকা একটি হাসপাতাল, গাড়ি থাকা একজন প্রতিবেশী। সাধারণত যা অভাব থাকে তা ইচ্ছা নয়, বরং সাহায্য প্রয়োজন এমন ব্যক্তিকে সাহায্য দিতে সক্ষম মানুষদের সাথে সংযুক্ত করার একটি দ্রুত, বিশ্বাসযোগ্য উপায়।",
  "about.problem2": "রেসকিউ ভারত সেই সমন্বয়ের জন্য একটি একক প্ল্যাটফর্ম: আজ নিখোঁজ ব্যক্তি, ওয়ান-ট্যাপ SOS, রক্তদান এবং দুর্যোগ প্রতিক্রিয়া, একই ভিত্তির উপর নির্মিত হাসপাতাল ডিরেক্টরি, অ্যাম্বুলেন্স অনুরোধ, স্বেচ্ছাসেবক নেটওয়ার্ক, এনজিও মামলা ব্যবস্থাপনা এবং আশ্রয়কেন্দ্র খোঁজার সাথে।",
  "about.believeHeading": "আমরা যা বিশ্বাস করি",
  "about.principle1Title": "বিশ্বাসই পণ্য",
  "about.principle1Desc": "একটি জরুরি প্ল্যাটফর্ম যতটা বিশ্বাসযোগ্য ততটাই কার্যকর। যাচাইকরণ, অডিট লগিং এবং ভূমিকা-ভিত্তিক অ্যাক্সেস এখানে পরবর্তী চিন্তা নয় — এগুলো মূল ভিত্তি।",
  "about.principle2Title": "গোপনীয়তা মানুষকে রক্ষা করে",
  "about.principle2Desc": "পাবলিক শেয়ার পৃষ্ঠাগুলো শুধুমাত্র কাউকে খুঁজে পেতে সাহায্যকারী তথ্য দেখায় — রিপোর্টকারীর যোগাযোগের বিবরণ, রোগীর চিকিৎসা ইতিহাস, বা মামলার জন্য প্রয়োজন নেই এমন কিছুই কখনো দেখায় না।",
  "about.principle3Title": "কমিউনিটিই কাজ করে",
  "about.principle3Desc": "স্বেচ্ছাসেবক, এনজিও, হাসপাতাল এবং দাতারাই প্রকৃতপক্ষে সাহায্য করেন — সঠিক সতর্কতা সঠিক ব্যক্তির কাছে দ্রুত পৌঁছে দেওয়াই প্ল্যাটফর্মের কাজ।",
  "about.principle4Title": "প্রকাশ্যে, সততার সাথে তৈরি",
  "about.principle4Desc": "আজ চারটি মডিউল লাইভ। বাকিগুলো মডিউল অনুযায়ী তৈরি করা হচ্ছে, কোনো বৈশিষ্ট্যই তা প্রকৃতপক্ষে এন্ড-টু-এন্ড পরীক্ষিত না হওয়া পর্যন্ত \"সম্পন্ন\" হিসেবে চিহ্নিত করা হয় না।",
  "about.liveHeading": "আজ যা লাইভ",
  "about.live1": "QR-কোড পাবলিক শেয়ার পৃষ্ঠা এবং দেখা যাওয়ার টাইমলাইন সহ নিখোঁজ ব্যক্তির রিপোর্টিং",
  "about.live2": "লাইভ লোকেশন এবং বিশ্বস্ত-পরিচিতি বিজ্ঞপ্তি সহ ওয়ান-ট্যাপ SOS",
  "about.live3": "দাতার প্রতিক্রিয়া ট্র্যাকিং সহ জরুরি রক্তদান অনুরোধ",
  "about.live4": "দুর্যোগ মোড অবস্থা রিপোর্টিং — নিরাপদ হিসেবে চিহ্নিত করুন, অথবা উদ্ধার, খাদ্য, পানি বা ওষুধের জন্য অনুরোধ করুন",
  "about.nextHeading": "এরপর যা আসছে",
  "about.nextText": "অতিরিক্ত যাচাইকরণ সহ নিখোঁজ শিশু এবং প্রবীণদের কর্মপ্রবাহ, হারানো পোষা প্রাণীর রিপোর্টিং, হাসপাতাল এবং অ্যাম্বুলেন্স সমন্বয়, দক্ষতা এবং সুনাম সহ একটি যাচাইকৃত স্বেচ্ছাসেবক নেটওয়ার্ক, এনজিও মামলা ড্যাশবোর্ড, আশ্রয়কেন্দ্র খোঁজা, একটি নেটিভ মোবাইল অ্যাপ, এবং মডারেশন ও বিশ্লেষণের জন্য অ্যাডমিন টুলিং — মোটামুটি সেই ক্রমে।",
  "about.createAccount": "অ্যাকাউন্ট তৈরি করুন",
  "about.backHome": "হোমে ফিরে যান",

