  "about.heading": "રેસ્ક્યૂ ભારત વિશે",
  "about.intro": "કોઈ ગુમ થવાની, કટોકટી શરૂ થવાની, અથવા આપત્તિ ત્રાટકવાની તરત પછીની મિનિટો સૌથી વધુ મહત્વની હોય છે — અને તે સામાન્ય રીતે મદદનું સંકલન કરવાને બદલે ફોન કોલ કરવામાં વિતાવવામાં આવે છે, તેથી જ રેસ્ક્યૂ ભારત અસ્તિત્વમાં છે.",
  "about.problemHeading": "અમે જે સમસ્યા માટે બનાવી રહ્યા છીએ",
  "about.problem1": "જ્યારે કુટુંબનો સભ્ય ગુમ થાય છે, કોઈ અજાણી વ્યક્તિ જાહેરમાં ઢળી પડે છે, અથવા પૂર કોઈ વિસ્તારને કાપી નાખે છે, ત્યારે મદદ કરવા માટે શ્રેષ્ઠ સ્થિતિમાં રહેલા લોકો ઘણીવાર નજીકમાં જ હોય છે — શોધ અને બચાવ તાલીમ ધરાવતો સ્વયંસેવક, ખાલી પથારીવાળી હોસ્પિટલ, કારવાળો પડોશી. સામાન્ય રીતે જે ખૂટે છે તે ઇચ્છા નથી, પરંતુ મદદની જરૂર હોય તેવી વ્યક્તિને મદદ આપી શકે તેવા લોકો સાથે જોડવાનો ઝડપી, વિશ્વસનીય માર્ગ છે.",
  "about.problem2": "રેસ્ક્યૂ ભારત તે સંકલન માટે એક જ પ્લેટફોર્મ છે: આજે ગુમ થયેલ વ્યક્તિઓ, વન-ટેપ SOS, રક્તદાન, અને આપત્તિ પ્રતિસાદ, તે જ પાયા પર બનેલ હોસ્પિટલ ડિરેક્ટરીઓ, એમ્બ્યુલન્સ વિનંતીઓ, સ્વયંસેવક નેટવર્ક, એનજીઓ કેસ મેનેજમેન્ટ, અને આશ્રયસ્થાન શોધ સાથે.",
  "about.believeHeading": "અમે શું માનીએ છીએ",
  "about.principle1Title": "વિશ્વાસ એ જ ઉત્પાદન છે",
  "about.principle1Desc": "કટોકટી પ્લેટફોર્મ જેટલું વિશ્વસનીય છે તેટલું જ ઉપયોગી છે. ચકાસણી, ઓડિટ લોગિંગ, અને ભૂમિકા-આધારિત એક્સેસ અહીં પછીના વિચારો નથી — તે પાયારૂપ છે.",
  "about.principle2Title": "ગોપનીયતા લોકોનું રક્ષણ કરે છે",
  "about.principle2Desc": "જાહેર શેર પેજ ફક્ત કોઈને શોધવામાં મદદરૂપ થાય તે જ બતાવે છે — રિપોર્ટ કરનારની સંપર્ક વિગતો, દર્દીનો તબીબી ઇતિહાસ, અથવા કેસ માટે જરૂરી ન હોય તેવું કંઈપણ ક્યારેય બતાવતું નથી.",
  "about.principle3Title": "સમુદાય જ કામ કરે છે",
  "about.principle3Desc": "સ્વયંસેવકો, એનજીઓ, હોસ્પિટલો, અને દાતાઓ જ ખરેખર મદદ કરે છે — યોગ્ય ચેતવણી યોગ્ય વ્યક્તિ સુધી ઝડપથી પહોંચાડવી એ પ્લેટફોર્મનું કામ છે.",
  "about.principle4Title": "ખુલ્લેઆમ, પ્રામાણિકતાથી બનાવેલ",
  "about.principle4Desc": "આજે ચાર મોડ્યુલો લાઇવ છે. બાકીના મોડ્યુલ પ્રમાણે મોડ્યુલ બનાવવામાં આવી રહ્યા છે, કોઈપણ સુવિધાને તે ખરેખર એન્ડ-ટુ-એન્ડ ચકાસાય ત્યાં સુધી \"પૂર્ણ\" તરીકે ચિહ્નિત કરવામાં આવતી નથી.",
  "about.liveHeading": "આજે શું લાઇવ છે",
  "about.live1": "QR-કોડ જાહેર શેર પેજ અને જોવા મળ્યાની સમયરેખાઓ સાથે ગુમ થયેલ વ્યક્તિની જાણ",
  "about.live2": "લાઇવ લોકેશન અને વિશ્વસનીય-સંપર્ક સૂચના સાથે વન-ટેપ SOS",
  "about.live3": "દાતાના પ્રતિસાદ ટ્રેકિંગ સાથે કટોકટી રક્તદાન વિનંતીઓ",
  "about.live4": "આપત્તિ મોડ સ્થિતિ રિપોર્ટિંગ — સુરક્ષિત તરીકે ચિહ્નિત કરો, અથવા બચાવ, ખોરાક, પાણી, અથવા દવાની વિનંતી કરો",
  "about.nextHeading": "આગળ શું આવી રહ્યું છે",
  "about.nextText": "વધારાની ચકાસણી સાથે ગુમ થયેલ બાળકો અને વૃદ્ધોના વર્કફ્લો, ખોવાયેલ પાળતુ પ્રાણી રિપોર્ટિંગ, હોસ્પિટલ અને એમ્બ્યુલન્સ સંકલન, કૌશલ્ય અને પ્રતિષ્ઠા સાથે ચકાસાયેલ સ્વયંસેવક નેટવર્ક, એનજીઓ કેસ ડેશબોર્ડ, આશ્રયસ્થાન શોધ, નેટિવ મોબાઇલ એપ, અને મોડરેશન અને એનાલિટિક્સ માટે એડમિન ટૂલિંગ — લગભગ તે જ ક્રમમાં.",
  "about.createAccount": "ખાતું બનાવો",
