  "nicci.micStart": "ਬੋਲੋ",
  "nicci.q.helpline": "ਐਮਰਜੈਂਸੀ ਹੈਲਪਲਾਈਨ",
  "nicci.q.about": "ਰੈਸਕਿਊ ਭਾਰਤ ਬਾਰੇ",
  "nicci.a.greeting": "ਨਮਸਕਾਰ! ਮੈਂ ਤੁਹਾਡਾ ਰੈਸਕਿਊ ਭਾਰਤ ਸਹਾਇਕ ਹਾਂ। ਕਿਸੇ ਵੀ ਸੇਵਾ ਬਾਰੇ ਪੁੱਛੋ — ਲਾਪਤਾ ਵਿਅਕਤੀ, SOS, ਖੂਨਦਾਨ, ਆਫ਼ਤ ਰਾਹਤ ਅਤੇ ਹੋਰ ਬਹੁਤ ਕੁਝ।",
  "nicci.a.greetingNamed": "ਨਮਸਕਾਰ {name}! ਮੈਂ ਤੁਹਾਡਾ ਰੈਸਕਿਊ ਭਾਰਤ ਸਹਾਇਕ ਹਾਂ। ਕਿਸੇ ਵੀ ਸੇਵਾ ਬਾਰੇ ਪੁੱਛੋ — ਲਾਪਤਾ ਵਿਅਕਤੀ, SOS, ਖੂਨਦਾਨ, ਆਫ਼ਤ ਰਾਹਤ ਅਤੇ ਹੋਰ ਬਹੁਤ ਕੁਝ।",
  "nicci.a.about": "ਰੈਸਕਿਊ ਭਾਰਤ ਇੱਕ ਭਾਈਚਾਰਕ ਐਮਰਜੈਂਸੀ ਪਲੇਟਫਾਰਮ ਹੈ। ਇਹ ਲਾਪਤਾ ਵਿਅਕਤੀ ਰਿਪੋਰਟਾਂ, SOS ਚੇਤਾਵਨੀਆਂ, ਖੂਨਦਾਨ, ਆਫ਼ਤ ਰਾਹਤ, ਮੁਹਿੰਮਾਂ ਅਤੇ ਭਾਈਚਾਰਕ ਮਦਦ ਨੂੰ ਇਕੱਠਾ ਕਰਦਾ ਹੈ — 10 ਭਾਰਤੀ ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ।",
  "nicci.a.helpline": "ਐਮਰਜੈਂਸੀ ਹੈਲਪਲਾਈਨ — ਸਾਰੀਆਂ ਐਮਰਜੈਂਸੀਆਂ 112, ਪੁਲਿਸ 100, ਐਂਬੂਲੈਂਸ 108, ਅੱਗ ਬੁਝਾਊ 101, ਮਹਿਲਾ 1091, ਬਾਲ 1098, ਆਫ਼ਤ 1077।",
  "nicci.a.languages": "ਰੈਸਕਿਊ ਭਾਰਤ 10 ਭਾਰਤੀ ਭਾਸ਼ਾਵਾਂ ਵਿੱਚ ਕੰਮ ਕਰਦਾ ਹੈ। ਪੰਨੇ ਦੇ ਉੱਪਰ ਭਾਸ਼ਾ ਮੇਨੂ ਤੋਂ ਕਿਸੇ ਵੀ ਸਮੇਂ ਬਦਲੋ।",
  "nicci.a.account": "ਕੇਸ ਰਿਪੋਰਟ ਕਰਨ, ਸਮਾਗਮਾਂ ਲਈ RSVP ਕਰਨ ਅਤੇ ਚੇਤਾਵਨੀਆਂ ਪ੍ਰਾਪਤ ਕਰਨ ਲਈ ਉੱਪਰ-ਸੱਜੇ ਮੇਨੂ ਤੋਂ ਸਾਈਨ ਅੱਪ ਜਾਂ ਲੌਗ ਇਨ ਕਰੋ।",
  "nicci.a.thanks": "ਮਦਦ ਕਰਕੇ ਖੁਸ਼ੀ ਹੋਈ! ਸੁਰੱਖਿਅਤ ਰਹੋ। 🙏",
  "nicci.a.fallback": "ਲਾਪਤਾ ਵਿਅਕਤੀ, SOS, ਖੂਨਦਾਨ, ਆਫ਼ਤ ਰਾਹਤ, ਮੁਹਿੰਮਾਂ, ਭਾਈਚਾਰਾ, ਕੈਲੰਡਰ ਅਤੇ ਐਮਰਜੈਂਸੀ ਹੈਲਪਲਾਈਨਾਂ ਵਿੱਚ ਮੈਂ ਮਦਦ ਕਰ ਸਕਦਾ ਹਾਂ। ਤੁਹਾਨੂੰ ਕੀ ਚਾਹੀਦਾ ਹੈ?",
