  "carousel.slide1Desc": "ਇੱਕ ਮਿੰਟ ਤੋਂ ਘੱਟ ਸਮੇਂ ਵਿੱਚ ਫੋਟੋਆਂ ਨਾਲ ਰਿਪੋਰਟ ਦਰਜ ਕਰੋ, ਅਤੇ QR ਕੋਡ ਰਾਹੀਂ ਤੁਰੰਤ ਸਾਂਝਾ ਕਰੋ।",
  "carousel.slide1Cta": "ਕਿਸੇ ਦੇ ਲਾਪਤਾ ਹੋਣ ਦੀ ਰਿਪੋਰਟ ਕਰੋ",
  "carousel.slide2Title": "ਇੱਕ ਟੈਪ ਤੁਹਾਡੇ ਵੱਲ ਮਦਦ ਭੇਜਦਾ ਹੈ",
  "carousel.slide2Desc": "SOS ਤੁਹਾਡਾ ਲਾਈਵ ਟਿਕਾਣਾ ਭਰੋਸੇਯੋਗ ਸੰਪਰਕਾਂ ਅਤੇ ਨੇੜਲੇ ਪ੍ਰਮਾਣਿਤ ਵਲੰਟੀਅਰਾਂ ਨਾਲ ਸਾਂਝਾ ਕਰਦਾ ਹੈ।",
  "carousel.slide2Cta": "ਦੇਖੋ SOS ਕਿਵੇਂ ਕੰਮ ਕਰਦਾ ਹੈ",
  "carousel.slide3Title": "ਨੇੜਲਾ ਦਾਨੀ ਅੱਜ ਇੱਕ ਜਾਨ ਬਚਾ ਸਕਦਾ ਹੈ",
  "carousel.slide3Desc": "ਜ਼ਰੂਰੀ ਖੂਨ ਦੀ ਬੇਨਤੀ ਪੋਸਟ ਕਰੋ ਜਾਂ ਦਾਨੀ ਵਜੋਂ ਰਜਿਸਟਰ ਕਰੋ — ਬਲੱਡ ਗਰੁੱਪ ਅਤੇ ਸ਼ਹਿਰ ਅਨੁਸਾਰ ਮੇਲ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
  "carousel.slide3Cta": "ਖੂਨ ਦੀਆਂ ਬੇਨਤੀਆਂ ਦੇਖੋ",
  "carousel.slide4Title": "ਆਫ਼ਤ ਆਉਣ 'ਤੇ ਤਾਲਮੇਲ ਵਾਲੀ ਪ੍ਰਤੀਕਿਰਿਆ",
  "carousel.slide4Desc": "ਸਰਗਰਮ ਆਫ਼ਤਾਂ ਦੌਰਾਨ ਆਪਣੇ ਆਪ ਨੂੰ ਸੁਰੱਖਿਅਤ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਕਰੋ, ਜਾਂ ਬਚਾਅ, ਭੋਜਨ, ਪਾਣੀ ਜਾਂ ਦਵਾਈ ਦੀ ਬੇਨਤੀ ਕਰੋ।",
