  "ticker.neededIn": "ਲੋੜੀਂਦਾ",
  "ticker.label": "ਲਾਈਵ ਅੱਪਡੇਟ",
  "ticker.fallback1": "📢 ਇੱਕ ਮਿੰਟ ਤੋਂ ਘੱਟ ਸਮੇਂ ਵਿੱਚ ਲਾਪਤਾ ਵਿਅਕਤੀ ਦੀ ਰਿਪੋਰਟ ਕਰੋ — QR ਕੋਡ ਰਾਹੀਂ ਤੁਰੰਤ ਸਾਂਝਾ ਕਰੋ",
