  "about.heading": "ਰੈਸਕਿਊ ਭਾਰਤ ਬਾਰੇ",
  "about.intro": "ਕਿਸੇ ਦੇ ਲਾਪਤਾ ਹੋਣ, ਐਮਰਜੈਂਸੀ ਸ਼ੁਰੂ ਹੋਣ, ਜਾਂ ਆਫ਼ਤ ਆਉਣ ਤੋਂ ਤੁਰੰਤ ਬਾਅਦ ਦੇ ਮਿੰਟ ਸਭ ਤੋਂ ਵੱਧ ਮਾਇਨੇ ਰੱਖਦੇ ਹਨ — ਅਤੇ ਇਹ ਆਮ ਤੌਰ 'ਤੇ ਮਦਦ ਦਾ ਤਾਲਮੇਲ ਕਰਨ ਦੀ ਬਜਾਏ ਫ਼ੋਨ ਕਾਲਾਂ ਕਰਨ ਵਿੱਚ ਬਿਤਾਏ ਜਾਂਦੇ ਹਨ, ਇਸੇ ਲਈ ਰੈਸਕਿਊ ਭਾਰਤ ਮੌਜੂਦ ਹੈ।",
  "about.problemHeading": "ਉਹ ਸਮੱਸਿਆ ਜਿਸ ਲਈ ਅਸੀਂ ਬਣਾ ਰਹੇ ਹਾਂ",
  "about.problem1": "ਜਦੋਂ ਪਰਿਵਾਰ ਦਾ ਕੋਈ ਮੈਂਬਰ ਲਾਪਤਾ ਹੋ ਜਾਂਦਾ ਹੈ, ਕੋਈ ਅਜਨਬੀ ਜਨਤਕ ਤੌਰ 'ਤੇ ਢਹਿ ਪੈਂਦਾ ਹੈ, ਜਾਂ ਹੜ੍ਹ ਕਿਸੇ ਇਲਾਕੇ ਨੂੰ ਕੱਟ ਦਿੰਦਾ ਹੈ, ਤਾਂ ਮਦਦ ਕਰਨ ਲਈ ਸਭ ਤੋਂ ਵਧੀਆ ਸਥਿਤੀ ਵਿੱਚ ਮੌਜੂਦ ਲੋਕ ਅਕਸਰ ਨੇੜੇ ਹੀ ਹੁੰਦੇ ਹਨ — ਖੋਜ ਅਤੇ ਬਚਾਅ ਸਿਖਲਾਈ ਵਾਲਾ ਇੱਕ ਵਲੰਟੀਅਰ, ਖਾਲੀ ਬਿਸਤਰੇ ਵਾਲਾ ਹਸਪਤਾਲ, ਕਾਰ ਵਾਲਾ ਗੁਆਂਢੀ। ਆਮ ਤੌਰ 'ਤੇ ਜੋ ਘਾਟ ਹੁੰਦੀ ਹੈ ਉਹ ਇੱਛਾ ਨਹੀਂ, ਸਗੋਂ ਮਦਦ ਦੀ ਲੋੜ ਵਾਲੇ ਵਿਅਕਤੀ ਨੂੰ ਮਦਦ ਦੇ ਸਕਣ ਵਾਲਿਆਂ ਨਾਲ ਜੋੜਨ ਦਾ ਇੱਕ ਤੇਜ਼, ਭਰੋਸੇਯੋਗ ਤਰੀਕਾ ਹੈ।",
  "about.problem2": "ਰੈਸਕਿਊ ਭਾਰਤ ਉਸ ਤਾਲਮੇਲ ਲਈ ਇੱਕ ਸਿੰਗਲ ਪਲੇਟਫਾਰਮ ਹੈ: ਅੱਜ ਲਾਪਤਾ ਵਿਅਕਤੀ, ਇੱਕ-ਟੈਪ SOS, ਖੂਨਦਾਨ, ਅਤੇ ਆਫ਼ਤ ਪ੍ਰਤੀਕਿਰਿਆ, ਉਸੇ ਬੁਨਿਆਦ 'ਤੇ ਬਣੇ ਹਸਪਤਾਲ ਡਾਇਰੈਕਟਰੀਆਂ, ਐਂਬੂਲੈਂਸ ਬੇਨਤੀਆਂ, ਵਲੰਟੀਅਰ ਨੈੱਟਵਰਕ, ਐਨਜੀਓ ਕੇਸ ਪ੍ਰਬੰਧਨ, ਅਤੇ ਆਸਰਾ ਖੋਜ ਦੇ ਨਾਲ।",
  "about.believeHeading": "ਅਸੀਂ ਕੀ ਮੰਨਦੇ ਹਾਂ",
  "about.principle1Title": "ਭਰੋਸਾ ਹੀ ਉਤਪਾਦ ਹੈ",
  "about.principle1Desc": "ਇੱਕ ਐਮਰਜੈਂਸੀ ਪਲੇਟਫਾਰਮ ਓਨਾ ਹੀ ਲਾਭਦਾਇਕ ਹੁੰਦਾ ਹੈ ਜਿੰਨਾ ਇਹ ਭਰੋਸੇਯੋਗ ਹੈ। ਤਸਦੀਕ, ਆਡਿਟ ਲੌਗਿੰਗ, ਅਤੇ ਭੂਮਿਕਾ-ਆਧਾਰਿਤ ਪਹੁੰਚ ਇੱਥੇ ਬਾਅਦ ਦੇ ਵਿਚਾਰ ਨਹੀਂ ਹਨ — ਇਹ ਬੁਨਿਆਦੀ ਹਨ।",
  "about.principle2Title": "ਗੋਪਨੀਯਤਾ ਲੋਕਾਂ ਦੀ ਰੱਖਿਆ ਕਰਦੀ ਹੈ",
  "about.principle2Desc": "ਜਨਤਕ ਸਾਂਝਾ ਪੰਨੇ ਸਿਰਫ਼ ਉਹੀ ਦਿਖਾਉਂਦੇ ਹਨ ਜੋ ਕਿਸੇ ਨੂੰ ਲੱਭਣ ਵਿੱਚ ਮਦਦ ਕਰਦਾ ਹੈ — ਰਿਪੋਰਟ ਕਰਨ ਵਾਲੇ ਦੇ ਸੰਪਰਕ ਵੇਰਵੇ, ਮਰੀਜ਼ ਦਾ ਮੈਡੀਕਲ ਇਤਿਹਾਸ, ਜਾਂ ਮਾਮਲੇ ਲਈ ਲੋੜੀਂਦੀ ਨਾ ਹੋਣ ਵਾਲੀ ਕੋਈ ਵੀ ਚੀਜ਼ ਕਦੇ ਨਹੀਂ ਦਿਖਾਉਂਦੇ।",
  "about.principle3Title": "ਕਮਿਊਨਿਟੀ ਹੀ ਕੰਮ ਕਰਦੀ ਹੈ",
  "about.principle3Desc": "ਵਲੰਟੀਅਰ, ਐਨਜੀਓ, ਹਸਪਤਾਲ, ਅਤੇ ਦਾਨੀ ਹੀ ਅਸਲ ਵਿੱਚ ਮਦਦ ਕਰਦੇ ਹਨ — ਸਹੀ ਚੇਤਾਵਨੀ ਸਹੀ ਵਿਅਕਤੀ ਤੱਕ ਤੇਜ਼ੀ ਨਾਲ ਪਹੁੰਚਾਉਣਾ ਪਲੇਟਫਾਰਮ ਦਾ ਕੰਮ ਹੈ।",
  "about.principle4Title": "ਖੁੱਲ੍ਹੇਆਮ, ਇਮਾਨਦਾਰੀ ਨਾਲ ਬਣਾਇਆ ਗਿਆ",
  "about.principle4Desc": "ਅੱਜ ਚਾਰ ਮੋਡੀਊਲ ਲਾਈਵ ਹਨ। ਬਾਕੀ ਮੋਡੀਊਲ ਦਰ ਮੋਡੀਊਲ ਬਣਾਏ ਜਾ ਰਹੇ ਹਨ, ਕਿਸੇ ਵੀ ਵਿਸ਼ੇਸ਼ਤਾ ਨੂੰ ਉਦੋਂ ਤੱਕ \"ਪੂਰਾ\" ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ ਜਦੋਂ ਤੱਕ ਇਸਦੀ ਅਸਲ ਵਿੱਚ ਐਂਡ-ਟੂ-ਐਂਡ ਜਾਂਚ ਨਹੀਂ ਹੋ ਜਾਂਦੀ।",
  "about.liveHeading": "ਅੱਜ ਕੀ ਲਾਈਵ ਹੈ",
  "about.live1": "QR-ਕੋਡ ਜਨਤਕ ਸਾਂਝਾ ਪੰਨਿਆਂ ਅਤੇ ਦਿਸਣ ਦੀਆਂ ਸਮਾਂ-ਰੇਖਾਵਾਂ ਨਾਲ ਲਾਪਤਾ ਵਿਅਕਤੀ ਦੀ ਰਿਪੋਰਟਿੰਗ",
  "about.live2": "ਲਾਈਵ ਟਿਕਾਣੇ ਅਤੇ ਭਰੋਸੇਯੋਗ-ਸੰਪਰਕ ਸੂਚਨਾ ਨਾਲ ਇੱਕ-ਟੈਪ SOS",
  "about.live3": "ਦਾਨੀ ਪ੍ਰਤੀਕਿਰਿਆ ਟਰੈਕਿੰਗ ਨਾਲ ਐਮਰਜੈਂਸੀ ਖੂਨਦਾਨ ਬੇਨਤੀਆਂ",
  "about.live4": "ਆਫ਼ਤ ਮੋਡ ਸਥਿਤੀ ਰਿਪੋਰਟਿੰਗ — ਸੁਰੱਖਿਅਤ ਵਜੋਂ ਚਿੰਨ੍ਹਿਤ ਕਰੋ, ਜਾਂ ਬਚਾਅ, ਭੋਜਨ, ਪਾਣੀ, ਜਾਂ ਦਵਾਈ ਦੀ ਬੇਨਤੀ ਕਰੋ",
  "about.nextHeading": "ਅੱਗੇ ਕੀ ਆ ਰਿਹਾ ਹੈ",
  "about.nextText": "ਵਾਧੂ ਤਸਦੀਕ ਨਾਲ ਲਾਪਤਾ ਬੱਚਿਆਂ ਅਤੇ ਬਜ਼ੁਰਗਾਂ ਦੇ ਵਰਕਫਲੋ, ਗੁਆਚੇ ਪਾਲਤੂ ਜਾਨਵਰ ਦੀ ਰਿਪੋਰਟਿੰਗ, ਹਸਪਤਾਲ ਅਤੇ ਐਂਬੂਲੈਂਸ ਤਾਲਮੇਲ, ਹੁਨਰ ਅਤੇ ਸਾਖ ਨਾਲ ਪ੍ਰਮਾਣਿਤ ਵਲੰਟੀਅਰ ਨੈੱਟਵਰਕ, ਐਨਜੀਓ ਕੇਸ ਡੈਸ਼ਬੋਰਡ, ਆਸਰਾ ਖੋਜ, ਇੱਕ ਨੇਟਿਵ ਮੋਬਾਈਲ ਐਪ, ਅਤੇ ਸੰਚਾਲਨ ਅਤੇ ਵਿਸ਼ਲੇਸ਼ਣ ਲਈ ਐਡਮਿਨ ਟੂਲਿੰਗ — ਲਗਭਗ ਉਸੇ ਕ੍ਰਮ ਵਿੱਚ।",
  "about.createAccount": "ਖਾਤਾ ਬਣਾਓ",
